"""Bottleneck analysis — computed from simulation traces, never generated by an LLM.

Evidence sources:
- blocked-hours per (SED, cause): missing utilities vs missing resources;
- resource utilization and capacity losses;
- queue peaks and unfinished instances;
- suspension counts (interrupted continuation).
"""

from __future__ import annotations

from typing import Any

from dtb.domain.model import EnterpriseModel
from dtb.simulation.result import SimulationResult

_UTILIZATION_THRESHOLD = 0.85


def analyze_bottlenecks(
    result: SimulationResult, model: EnterpriseModel | None = None
) -> list[dict[str, Any]]:
    """Ranked list of evidence-backed bottlenecks."""
    findings: list[dict[str, Any]] = []

    def name_of(collection: str, entity_id: str) -> str:
        if model is None:
            return entity_id
        entity = model.collection(collection).get(entity_id) if collection else None
        return entity.name if entity is not None and entity.name else entity_id

    for sed_id, stats in result.sed_stats.items():
        for cause, hours in stats.get("blocked_hours", {}).items():
            if hours <= 0:
                continue
            kind, _, ref = cause.partition(":")
            if kind == "utility":
                findings.append(
                    {
                        "type": "missing_utility",
                        "severity": hours,
                        "sed_id": sed_id,
                        "sed_name": name_of("sed", sed_id),
                        "utility_type_id": ref,
                        "utility_name": name_of("utility_type", ref),
                        "blocked_hours": round(hours, 2),
                        "evidence": f"СЭД '{name_of('sed', sed_id)}' ждал полезность "
                        f"'{name_of('utility_type', ref)}' {hours:.1f} ч",
                    }
                )
            elif kind == "resource":
                findings.append(
                    {
                        "type": "missing_resource",
                        "severity": hours,
                        "sed_id": sed_id,
                        "sed_name": name_of("sed", sed_id),
                        "resource_id": ref,
                        "resource_name": name_of("resource", ref),
                        "blocked_hours": round(hours, 2),
                        "evidence": f"СЭД '{name_of('sed', sed_id)}' ждал ресурс "
                        f"'{name_of('resource', ref)}' {hours:.1f} ч",
                    }
                )
        queue_peak = stats.get("queue_peak", 0)
        still_waiting = stats.get("still_waiting", 0)
        if queue_peak >= 5 or still_waiting >= 3:
            findings.append(
                {
                    "type": "queue_accumulation",
                    "severity": float(queue_peak + still_waiting * 2),
                    "sed_id": sed_id,
                    "sed_name": name_of("sed", sed_id),
                    "queue_peak": queue_peak,
                    "unfinished": still_waiting,
                    "evidence": f"Очередь к СЭД '{name_of('sed', sed_id)}': пик {queue_peak}, "
                    f"не завершено {still_waiting}",
                }
            )
        suspensions = stats.get("suspensions", 0)
        if suspensions > 0:
            findings.append(
                {
                    "type": "interrupted_execution",
                    "severity": float(suspensions),
                    "sed_id": sed_id,
                    "sed_name": name_of("sed", sed_id),
                    "suspensions": suspensions,
                    "evidence": f"СЭД '{name_of('sed', sed_id)}' приостанавливался "
                    f"{suspensions} раз (потеря ресурсов/условий)",
                }
            )

    for res_id, stats in result.resource_stats.items():
        utilization = stats.get("utilization", 0.0)
        if utilization >= _UTILIZATION_THRESHOLD:
            findings.append(
                {
                    "type": "resource_saturation",
                    "severity": utilization * 100,
                    "resource_id": res_id,
                    "resource_name": name_of("resource", res_id),
                    "utilization": utilization,
                    "evidence": f"Ресурс '{name_of('resource', res_id)}' загружен на "
                    f"{utilization * 100:.0f}% — критическая зависимость",
                }
            )

    findings.sort(key=lambda f: -f["severity"])
    return findings
